/**
 * Enterprise conversations: personal channels, per the conversations-subsystem spec §4.1
 * (docs/superpowers/specs/enterprise-conversations-subsystem.md).
 *
 * A channel is one person's conversation with one bot: the owner is the member who created it, the
 * bot is a live ACL reference into `enterprise_resources` (kind='bot', enforced by the composite
 * FK — a channel cannot outlive the resource it points at), and the thread id is generated by the
 * server. The `(tenant_id, owner_principal_id, client_request_id)` unique constraint is the
 * creation idempotency linearization point; the `(tenant_id, owner_principal_id, status, id)`
 * index serves the owner's page. Channels are deliberately NOT rows in `enterprise_resources`:
 * their authorization predicate is owner equality, not an ACL grant, and their status vocabulary
 * ('active'/'archived') is a different lifecycle from resources ('active'/'deleted').
 *
 * Only the conversations domain (server/src/enterprise/conversations/) writes this table, and only
 * through `withTenant`; grants, memberships and resources stay owned by the tenancy domain. RLS
 * and the restricted logins' privileges live in migration 0058 (the 0056 pattern): the data login
 * may read/insert/update its own tenant's rows and nothing else.
 */
import { sql } from "drizzle-orm";
import {
  check,
  foreignKey,
  index,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
} from "drizzle-orm/pg-core";
import { enterpriseResources } from "./enterprise-authz";
import { enterpriseMemberships } from "./enterprise-tenancy";

export const enterpriseChannels = pgTable(
  "enterprise_channels",
  {
    tenantId: text("tenant_id").notNull(),
    id: text("id").notNull(),
    ownerPrincipalId: text("owner_principal_id").notNull(),
    botResourceId: text("bot_resource_id").notNull(),
    threadId: text("thread_id").notNull(),
    clientRequestId: text("client_request_id").notNull(),
    status: text("status").notNull().default("active"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    /* Set once at the first archive; a repeated archive rewrites neither it nor the row's identity. */
    archivedAt: timestamp("archived_at", { withTimezone: true }),
  },
  (t) => [
    // The same composite pattern as enterprise_resources: one keyspace per tenant.
    primaryKey({ columns: [t.tenantId, t.id] }),
    // The owner must be a member of the same tenant.
    foreignKey({
      name: "enterprise_channel_owner",
      columns: [t.tenantId, t.ownerPrincipalId],
      foreignColumns: [
        enterpriseMemberships.tenantId,
        enterpriseMemberships.principalId,
      ],
    }),
    // The bot is a same-tenant live reference into the ACL-owned resources, never a copied name.
    foreignKey({
      name: "enterprise_channel_bot",
      columns: [t.tenantId, t.botResourceId],
      foreignColumns: [enterpriseResources.tenantId, enterpriseResources.id],
    }),
    // The creation idempotency linearization point (spec §5).
    unique("enterprise_channel_client_request").on(
      t.tenantId,
      t.ownerPrincipalId,
      t.clientRequestId,
    ),
    check(
      "enterprise_channel_status",
      sql`${t.status} in ('active','archived')`,
    ),
    // The owner's page scan (spec §4.1).
    index("enterprise_channels_owner_status_idx").on(
      t.tenantId,
      t.ownerPrincipalId,
      t.status,
      t.id,
    ),
  ],
);
